<?php
namespace Tests\Feature;use App\Models\User;use Database\Seeders\DatabaseSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Spatie\Permission\Models\{Permission,Role};use Tests\TestCase;
class AccessControlCrudTest extends TestCase{use RefreshDatabase;private User $admin;protected function setUp():void{parent::setUp();$this->seed(DatabaseSeeder::class);$this->admin=User::where('email','superadmin@admin.com')->firstOrFail();$this->actingAs($this->admin);}
 public function test_user_crud_filter_and_role_relation():void{$role=Role::firstOrCreate(['name'=>'editor','guard_name'=>'web']);$this->post(route('users.store'),['name'=>'Content Editor','email'=>'editor@example.com','password'=>'Password123','role'=>$role->name])->assertRedirect();$user=User::where('email','editor@example.com')->firstOrFail();$this->assertTrue($user->hasRole('editor'));$this->get(route('users.index',['q'=>'Content Editor','role'=>'editor']))->assertOk()->assertSee('editor@example.com');$this->put(route('users.update',$user),['name'=>'Updated Editor','email'=>'updated@example.com','role'=>'editor'])->assertRedirect();$this->assertDatabaseHas('users',['id'=>$user->id,'name'=>'Updated Editor']);$this->delete(route('users.destroy',$user))->assertRedirect();$this->assertDatabaseMissing('users',['id'=>$user->id]);}
 public function test_role_crud_filter_and_permissions_relation():void{$permission=Permission::firstOrCreate(['name'=>'test-content','guard_name'=>'web'],['group_name'=>'test']);$this->post(route('roles.store'),['name'=>'content-manager','permission'=>[$permission->name]])->assertRedirect();$role=Role::where('name','content-manager')->firstOrFail();$this->assertTrue($role->hasPermissionTo($permission));$this->get(route('roles.index',['q'=>'content-manager']))->assertOk()->assertSee('content-manager');$this->put(route('roles.update',$role),['name'=>'content-lead','permission'=>[]])->assertRedirect();$this->assertDatabaseHas('roles',['id'=>$role->id,'name'=>'content-lead']);$this->delete(route('roles.destroy',$role))->assertRedirect();$this->assertDatabaseMissing('roles',['id'=>$role->id]);}
 public function test_permission_crud_and_filter():void{$this->post(route('permissions.store'),['name'=>'publish-special','group_name'=>'publishing'])->assertRedirect();$permission=Permission::where('name','publish-special')->firstOrFail();$this->get(route('permissions.index',['q'=>'publish-special','group'=>'publishing']))->assertOk()->assertSee('publish-special');$this->put(route('permissions.update',$permission),['name'=>'publish-featured','group_name'=>'publishing'])->assertRedirect();$this->assertDatabaseHas('permissions',['id'=>$permission->id,'name'=>'publish-featured']);$this->delete(route('permissions.destroy',$permission))->assertRedirect();$this->assertDatabaseMissing('permissions',['id'=>$permission->id]);}
 public function test_update_actions_are_forbidden_without_permissions():void{$ordinary=User::factory()->create();$target=User::factory()->create();$role=Role::firstOrCreate(['name'=>'temporary','guard_name'=>'web']);$permission=Permission::firstOrCreate(['name'=>'temporary-action','guard_name'=>'web']);$this->actingAs($ordinary)->put(route('users.update',$target),['name'=>'Bad','email'=>'bad@example.com','role'=>'temporary'])->assertForbidden();$this->put(route('roles.update',$role),['name'=>'changed'])->assertForbidden();$this->put(route('permissions.update',$permission),['name'=>'changed','group_name'=>'x'])->assertForbidden();}
}
